-- 1081: Assembly Molding calculators -- the insert loading and the insert molding shot cycle as real database calculators.
--
-- GENERATED by scripts/generate-assembly-molding-calculators-migration.ts from
-- src/modules/bom-items/costing/plastic-molding/insert/calculators/assembly-molding-calculators.json.
-- Do not edit by hand: change the spec and regenerate.
--
-- ROOT CAUSE
--
-- Assembly Molding (insert molding) was staged (reference data 2026-AssyMolding; 254 HR Rates machines) but had no cost engine: the
-- loading of the inserts every shot (Insert Pick and Place) had no calculator. The molding itself is injection molding on an insert press
-- (migration 1080 links it to the injection cycle-time calculator); the shot cycle is a helper the engine runs to overlap the loading with
-- the molding on a rotary or shuttle table, which no operation maps to.
--
-- This migration creates one global calculator per spec entry (inputs are the
-- values the cost engine seeds, each shown with its source in the calculation
-- trace; calculated fields are the formulas the engine evaluates, it holds
-- none) and links every Assembly Molding catalog operation it computes to its
-- calculator in process_calculator_mappings.
--
-- Requires migration 804 (calculators.retired_at).
-- Self-contained, idempotent, post-checked.

BEGIN;

-- Assembly Molding - Insert loading
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Assembly Molding - Insert loading$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Assembly Molding - Insert loading$q$, 'process', 'single', false, true, true, $q$Loading a shot's inserts into the mold, by hand or by robot: each insert's load time by its weight and the load method (componentLoadTime: Manual or Robotic, the first row whose weight takes it), summed over the inserts of every cavity; a manual load is slowed by handlingMultiplier and insertionMultiplier for handling and seating the insert.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$Loading a shot's inserts into the mold, by hand or by robot: each insert's load time by its weight and the load method (componentLoadTime: Manual or Robotic, the first row whose weight takes it), summed over the inserts of every cavity; a manual load is slowed by handlingMultiplier and insertionMultiplier for handling and seating the insert.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Load Time$q$, $q$Load Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Manual Load$q$, $q$Manual Load$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Handling Multiplier$q$, $q$Handling Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Insertion Multiplier$q$, $q$Insertion Multiplier$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Cycle Time Factor$q$, $q$Cycle Time Factor$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Load Time} * ({Manual Load} * {Handling Multiplier} * {Insertion Multiplier} + 1 - {Manual Load}) * {Cycle Time Factor}$q$, 6, false);

  UPDATE public.process_calculator_mappings
  SET calculator_id = v_id, calculator_name = $q$Assembly Molding - Insert loading$q$, is_active = is_active OR machine_class IS NOT NULL
  WHERE process_group = $q$Assembly Molding$q$ AND operation IN ($q$Insert Pick and Place$q$);
END
$calc$;

-- Assembly Molding - Shot cycle
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Assembly Molding - Shot cycle$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Assembly Molding - Shot cycle$q$, 'process', 'single', false, true, true, $q$One shot of an insert molding press: on a press with a rotary or shuttle table the next lower mold half is loaded while the other is molded (defaultNumMoldToolsPerTable halves), so the shot takes the longer of the two; on a press with no table the inserts are loaded with the mold open, so the two add.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET calc_category = 'process', description = $q$One shot of an insert molding press: on a press with a rotary or shuttle table the next lower mold half is loaded while the other is molded (defaultNumMoldToolsPerTable halves), so the shot takes the longer of the two; on a press with no table the inserts are loaded with the mold open, so the two add.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Molding Cycle$q$, $q$Molding Cycle (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Load Time$q$, $q$Load Time (s)$q$, $q$number$q$, $q$s$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Table Press$q$, $q$Table Press$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Shot Cycle$q$, $q$Shot Cycle (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Table Press} * max({Molding Cycle}, {Load Time}) + (1 - {Table Press}) * ({Molding Cycle} + {Load Time})$q$, 4, false);
END
$calc$;

-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Assembly Molding - Insert loading$q$, 6, 1),
    ($q$Assembly Molding - Shot cycle$q$, 4, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Assembly Molding$q$ AND (m.is_active OR m.machine_class IS NULL)) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1081: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
